class TestOutputAU final:public ausdk::MusicDeviceBase {
public:
    explicit TestOutputAU(AudioUnit instance):MusicDeviceBase(instance,0,1),entry_(ravet_performance_processor_v1(32)),core_(entry_->create()){CreateElements();}
    ~TestOutputAU()override{if(core_)entry_->destroy(core_);}
    bool CanScheduleParameters()const noexcept override{return false;}
    bool StreamFormatWritable(AudioUnitScope scope,AudioUnitElement element)override{return !IsInitialized()&&scope==kAudioUnitScope_Output&&!element;}
    OSStatus Initialize()override{if(!core_)return kAudioUnitErr_FailedInitialization;const auto initialized=MusicDeviceBase::Initialize();if(initialized)return initialized;RavetNativeProcessorConfigV1 config{};config.version=1;config.maximum_frames=GetMaxFramesPerSlice();config.maximum_events=1024;config.bus_count=1;config.sample_rate=Output(0).GetStreamFormat().mSampleRate;config.buses[0]={0,1};return entry_->prepare(core_,&config)?OSStatus(kAudioUnitErr_FailedInitialization):OSStatus(noErr);}
    void Cleanup()override{if(core_)entry_->deactivate(core_);queue_.count=0;MusicDeviceBase::Cleanup();}
    bool ValidFormat(AudioUnitScope scope,AudioUnitElement element,const AudioStreamBasicDescription &format)override{return scope==kAudioUnitScope_Output&&!element&&std::isfinite(format.mSampleRate)&&format.mSampleRate>0.&&format.mFormatID==kAudioFormatLinearPCM&&format.mChannelsPerFrame==1&&format.mBitsPerChannel==32&&format.mBytesPerFrame==4&&format.mBytesPerPacket==4&&format.mFramesPerPacket==1&&(format.mFormatFlags==kAudioFormatFlagsNativeFloatPacked||format.mFormatFlags==(UInt32(kAudioFormatFlagsNativeFloatPacked)|UInt32(kAudioFormatFlagIsNonInterleaved)));}
    OSStatus GetPropertyInfo(AudioUnitPropertyID id,AudioUnitScope scope,AudioUnitElement element,UInt32 &size,bool &writable)override{
        if(id==kAudioUnitProperty_MIDIOutputCallbackInfo||id==kAudioUnitProperty_MIDIOutputCallback||id==queueProperty||id==processCountProperty||id==deliveryProperty){if(scope!=kAudioUnitScope_Global||element)return kAudioUnitErr_InvalidScope;size=id==kAudioUnitProperty_MIDIOutputCallbackInfo?sizeof(CFArrayRef):id==kAudioUnitProperty_MIDIOutputCallback?sizeof(AUMIDIOutputCallbackStruct):id==queueProperty?sizeof(Queue):id==deliveryProperty?sizeof(ravet::au::MidiOutputDelivery):sizeof(UInt32);writable=id==kAudioUnitProperty_MIDIOutputCallback||id==queueProperty;return noErr;}return MusicDeviceBase::GetPropertyInfo(id,scope,element,size,writable);
    }
    OSStatus GetProperty(AudioUnitPropertyID id,AudioUnitScope scope,AudioUnitElement element,void *data)override{
        if(!data)return kAudioUnitErr_InvalidPropertyValue;if(id==kAudioUnitProperty_MIDIOutputCallbackInfo||id==processCountProperty||id==deliveryProperty){if(scope!=kAudioUnitScope_Global||element)return kAudioUnitErr_InvalidScope;if(id==kAudioUnitProperty_MIDIOutputCallbackInfo){const void *names[]{CFSTR("Synthetic native MIDI")};const auto array=CFArrayCreate(nullptr,names,1,&kCFTypeArrayCallBacks);if(!array)return kAudioUnitErr_FailedInitialization;*static_cast<CFArrayRef *>(data)=array;}else if(id==processCountProperty)*static_cast<UInt32 *>(data)=processCount_;else*static_cast<ravet::au::MidiOutputDelivery *>(data)=delivery_;return noErr;}return MusicDeviceBase::GetProperty(id,scope,element,data);
    }
    OSStatus SetProperty(AudioUnitPropertyID id,AudioUnitScope scope,AudioUnitElement element,const void *data,UInt32 size)override{
        if(id==kAudioUnitProperty_MIDIOutputCallback||id==queueProperty){if(scope!=kAudioUnitScope_Global||element||!data||size!=(id==queueProperty?sizeof(Queue):sizeof(AUMIDIOutputCallbackStruct)))return kAudioUnitErr_InvalidPropertyValue;if(id==kAudioUnitProperty_MIDIOutputCallback){if(IsInitialized())return kAudioUnitErr_CannotDoInCurrentContext;std::memcpy(&callback_,data,sizeof(callback_));}else{const auto &queue=*static_cast<const Queue *>(data);if(queue.count>1024)return kAudioUnitErr_InvalidPropertyValue;queue_=queue;}return noErr;}return MusicDeviceBase::SetProperty(id,scope,element,data,size);
    }
    OSStatus Render(AudioUnitRenderActionFlags &flags,const AudioTimeStamp &time,UInt32 frames)noexcept override{
        // Test-owned postprocessor queue is synthetic; native Performance itself
        // generates no MIDI and completion remains suppressed in this profile.
        if(!output_.stage(queue_.events.data(),queue_.count,frames))return kAudioUnitErr_InvalidParameterValue;
        auto &buffer=Output(0).GetBufferList();float *channels[]{frames?static_cast<float *>(buffer.mBuffers[0].mData):nullptr};const RavetNativeProcessorBusV1 bus{0,1,nullptr,frames?channels:nullptr};RavetNativeProcessorResultV1 result{};++processCount_;
        if(entry_->process(core_,&bus,1,frames,nullptr,0,nullptr,nullptr,0,&result)||result.status>1||result.event_count)return kAudioUnitErr_InvalidParameterValue;
        delivery_=output_.deliver(callback_,&time,0);queue_.count=0;flags|=kAudioUnitRenderAction_OutputIsSilence;return noErr;
    }
    OSStatus renderCaller(AudioUnitRenderActionFlags *flags,const AudioTimeStamp *time,UInt32 bus,UInt32 frames,AudioBufferList *buffers){if(!time||!buffers)return kAudio_ParamError;AudioUnitRenderActionFlags temporary{};auto &actual=flags?*flags:temporary;const auto status=DoRender(actual,*time,bus,frames,*buffers);if(status&&bus==0&&buffers->mNumberBuffers==1&&buffers->mBuffers[0].mNumberChannels==1){auto &buffer=buffers->mBuffers[0];const auto count=std::min({frames,GetMaxFramesPerSlice(),buffer.mDataByteSize/UInt32(4)});if(buffer.mData&&reinterpret_cast<uintptr_t>(buffer.mData)%alignof(float)==0){std::fill_n(static_cast<float *>(buffer.mData),count,0.f);if(count==frames)actual|=kAudioUnitRenderAction_OutputIsSilence;}}return status;}
private:
    const RavetNativeProcessorEntryV1 *entry_;void *core_;Queue queue_{};UInt32 processCount_=0;ravet::au::NativeAuMidiOutput<> output_;AUMIDIOutputCallbackStruct callback_{};ravet::au::MidiOutputDelivery delivery_{ravet::au::MidiOutputRejection::NotStaged,0,noErr};
};
OSStatus render(void *self,AudioUnitRenderActionFlags *flags,const AudioTimeStamp *time,UInt32 bus,UInt32 frames,AudioBufferList *buffers){auto *instance=static_cast<ausdk::AudioComponentPlugInInstance *>(self);return reinterpret_cast<TestOutputAU *>(&instance->mInstanceStorage)->renderCaller(flags,time,bus,frames,buffers);}
struct OutputLookup{static AudioComponentMethod Lookup(SInt16 selector){return selector==kAudioUnitRenderSelect?reinterpret_cast<AudioComponentMethod>(render):ausdk::AUMusicLookup::Lookup(selector);}};
AudioComponentPlugInInterface *factory(const AudioComponentDescription *description){return static_cast<AudioComponentPlugInInterface *>(ausdk::APFactory<OutputLookup,TestOutputAU>::Factory(description));}
void require(bool value,const char *text){if(!value)throw std::runtime_error(text);}
void okay(OSStatus status,const char *text){if(status){std::cerr<<text<<": "<<status<<'\n';throw std::runtime_error(text);}}
struct Host{uint32_t calls=0,messages=0;OSStatus status=0;Float64 sample=0.;bool valid=true;};
OSStatus hostCallback(void *user,const AudioTimeStamp *time,UInt32 output,const MIDIPacketList *list){auto &host=*static_cast<Host *>(user);++host.calls;host.sample=time->mSampleTime;host.valid=host.valid&&output==0&&time->mFlags==kAudioTimeStampSampleTimeValid;const auto *packet=&list->packet[0];host.messages=0;for(UInt32 i=0;i<list->numPackets;++i){host.valid=host.valid&&packet->timeStamp==3;for(UInt32 j=0;j<packet->length;j+=3){host.valid=host.valid&&j+3<=packet->length&&packet->data[j]==0x9f&&packet->data[j+1]==69&&packet->data[j+2]==64;++host.messages;}packet=MIDIPacketNext(packet);}return host.status;}
void contracts(){AudioComponentDescription description{'aumu','RvMO','Ravt',0,0};const auto component=AudioComponentRegister(&description,CFSTR("Synthetic native MIDI output contracts"),256,factory);require(component,"in-process synthetic component registration");AudioUnit unit=nullptr;okay(AudioComponentInstanceNew(component,&unit),"synthetic instance");
    UInt32 size=0;Boolean writable=true;okay(AudioUnitGetPropertyInfo(unit,kAudioUnitProperty_MIDIOutputCallbackInfo,kAudioUnitScope_Global,0,&size,&writable),"MIDI output metadata info");require(size==sizeof(CFArrayRef)&&!writable,"typed read-only output metadata");CFArrayRef names=nullptr;size=sizeof(names);okay(AudioUnitGetProperty(unit,kAudioUnitProperty_MIDIOutputCallbackInfo,kAudioUnitScope_Global,0,&names,&size),"host retained output name array");require(names&&CFArrayGetCount(names)==1&&CFEqual(CFArrayGetValueAtIndex(names,0),CFSTR("Synthetic native MIDI")),"explicit independent MIDI output name");
    require(AudioUnitGetPropertyInfo(unit,kAudioUnitProperty_MIDIOutputCallbackInfo,kAudioUnitScope_Output,0,&size,&writable)!=noErr,"metadata wrong scope rejects");Host host;AUMIDIOutputCallbackStruct callback{hostCallback,&host};
    // AudioToolbox normalizes legacy output setters and additionally installs its
    // protocol adapter before SDK dispatch. Probe original sizes at raw SDK ABI.
    auto *raw=factory(&description);require(raw,"raw SDK factory");okay(raw->Open(raw,unit),"raw SDK instance");using Setter=OSStatus(*)(void *,AudioUnitPropertyID,AudioUnitScope,AudioUnitElement,const void *,UInt32);const auto set=reinterpret_cast<Setter>(raw->Lookup(kAudioUnitSetPropertySelect));require(set&&set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback)-1)!=noErr,"raw SDK exact callback size preflight");require(set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback)+1)!=noErr,"raw SDK excess callback size preflight");require(set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,nullptr,sizeof(callback))!=noErr,"raw SDK missing callback bytes");require(set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,1,&callback,sizeof(callback))!=noErr&&set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Output,0,&callback,sizeof(callback))!=noErr,"raw SDK exact callback scope/element preflight");okay(set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback)),"raw SDK callback install");using Lifecycle=OSStatus(*)(void *);const auto initialize=reinterpret_cast<Lifecycle>(raw->Lookup(kAudioUnitInitializeSelect));const auto stop=reinterpret_cast<Lifecycle>(raw->Lookup(kAudioUnitUninitializeSelect));okay(initialize(raw),"raw native preparation");require(set(raw,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback))!=noErr,"raw SDK stopped-only callback lifecycle");okay(stop(raw),"raw native stop");okay(raw->Close(raw),"raw SDK retirement");
    okay(AudioUnitSetProperty(unit,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback)-1),"public facade normalizes legacy callback size before owned dispatch");okay(AudioUnitSetProperty(unit,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,1,&callback,sizeof(callback)),"public facade normalizes legacy callback element before owned dispatch");okay(AudioUnitSetProperty(unit,kAudioUnitProperty_MIDIOutputCallback,kAudioUnitScope_Global,0,&callback,sizeof(callback)),"stopped callback ownership");callback={};
    AudioStreamBasicDescription format{};format.mSampleRate=48000.;format.mFormatID=kAudioFormatLinearPCM;format.mFormatFlags=UInt32(kAudioFormatFlagsNativeFloatPacked)|UInt32(kAudioFormatFlagIsNonInterleaved);format.mBytesPerPacket=format.mBytesPerFrame=4;format.mFramesPerPacket=1;format.mChannelsPerFrame=1;format.mBitsPerChannel=32;okay(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Output,0,&format,sizeof(format)),"prepared test mono format");UInt32 maximum=64;okay(AudioUnitSetProperty(unit,kAudioUnitProperty_MaximumFramesPerSlice,kAudioUnitScope_Global,0,&maximum,sizeof(maximum)),"bounded test frames");okay(AudioUnitInitialize(unit),"test initialize/native prepare");
    Queue queue{};queue.count=1024;for(auto &event:queue.events){event.kind=RAVET_NATIVE_NOTE_ON;event.offset=3;event.channel=15;event.key=69;event.value=double(.5f);}auto queued=[&](){okay(AudioUnitSetProperty(unit,queueProperty,kAudioUnitScope_Global,0,&queue,sizeof(queue)),"test-owned generated queue");};queued();
    std::array<float,65> samples{};AudioTimeStamp time{};time.mFlags=kAudioTimeStampSampleTimeValid;time.mSampleTime=-123.5;auto renderBlock=[&](){samples.fill(99.f);AudioBufferList buffers{1,{{1,64*4,samples.data()}}};AudioUnitRenderActionFlags flags=0;const auto status=AudioUnitRender(unit,&flags,&time,0,64,&buffers);time.mSampleTime+=64;require(samples[64]==99.f,"supported backing tail remains");for(UInt32 i=0;i<64;++i)require(samples[i]==0.f,"actual native silent output/fault prefix");return status;};okay(renderBlock(),"actual generated host output render");require(host.calls==1&&host.messages==1024&&host.sample==-123.5&&host.valid,"actual full MIDI output callback exact render timestamp/offset/policy");okay(renderBlock(),"empty next block");require(host.calls==1,"actual accepted output no replay");
    host.status=-77;queue.count=1;queued();okay(renderBlock(),"host refusal retains successful audio rendering");ravet::au::MidiOutputDelivery receipt{};size=sizeof(receipt);okay(AudioUnitGetProperty(unit,deliveryProperty,kAudioUnitScope_Global,0,&receipt,&size),"explicit consumer host-refusal receipt");require(receipt.reason==ravet::au::MidiOutputRejection::HostRejected&&receipt.hostStatus==-77&&receipt.attempted==1&&host.calls==2,"actual callback refusal/status without invented acceptance count");okay(renderBlock(),"next block after refusal");require(host.calls==2,"actual refused list not retried");host.status=0;
    UInt32 calls=0;size=sizeof(calls);okay(AudioUnitGetProperty(unit,processCountProperty,kAudioUnitScope_Global,0,&calls,&size),"native process counter");queue.count=1024;queue.events[1023].kind=RAVET_NATIVE_NOTE_END;queued();require(renderBlock()!=noErr,"late unsupported generated record rejects whole block");UInt32 retained=0;size=sizeof(retained);okay(AudioUnitGetProperty(unit,processCountProperty,kAudioUnitScope_Global,0,&retained,&size),"native counter after full output fault");require(retained==calls&&host.calls==2,"late output preflight performs no DSP or host callback");queue.events[1023].kind=RAVET_NATIVE_NOTE_ON;queued();okay(renderBlock(),"fresh accepted output after malformed block");require(host.calls==3&&host.messages==1024&&host.valid,"actual fresh complete output recovery");
    okay(AudioUnitUninitialize(unit),"test native stop");okay(AudioComponentInstanceDispose(unit),"test dispose");require(CFArrayGetCount(names)==1&&CFEqual(CFArrayGetValueAtIndex(names,0),CFSTR("Synthetic native MIDI")),"host-owned metadata survives component retirement");CFRelease(names);
}
